<section ng-controller="tarifController" ng-cloak>
<div class="alert alert-danger" ng-if="errorMessage" ng-bind="errorMessage"></div><div class="alert alert-success" ng-if="successMessage" ng-bind="successMessage"></div><div class="alert alert-warning" ng-if="!loading&&!activePeriod">Belum ada periode aktif. Tarif baru belum dapat dibuat.</div>
<article class="card sitara-card"><header class="card-header border-0 pb-0"><div class="module-toolbar d-flex flex-column flex-lg-row justify-content-between align-items-lg-center gap-3"><div><h2 class="sitara-card-title">Tarif periode aktif</h2><p class="sitara-card-subtitle mb-0" ng-if="activePeriod" ng-bind="activePeriod.academic_year_code+' — '+activePeriod.semester_code"></p></div><div class="d-flex gap-2"><input class="form-control form-control-sm" type="search" placeholder="Cari prodi, kegiatan, atau jalur" ng-model="searchText"><button class="btn btn-sm btn-primary text-nowrap" type="button" ng-click="openCreate()" ng-disabled="!activePeriod">Tambah tarif</button></div></div></header><div class="table-responsive mt-3"><table class="table sitara-table mb-0"><thead><tr><th>Program Studi</th><th>Kegiatan</th><th>Jalur Ujian</th><th>Versi</th><th>Komponen</th><th class="text-end">Total</th><th class="text-end">Aksi</th></tr></thead><tbody><tr ng-if="loading"><td colspan="7" class="sitara-empty">Memuat tarif...</td></tr><tr ng-repeat="x in (filteredDatas=(datas|filter:searchText)) track by x.id"><td><div class="table-main" ng-bind="x.program_code"></div><small ng-bind="x.program_name"></small></td><td><div class="table-main" ng-bind="x.activity_name"></div><small ng-bind="x.activity_code"></small></td><td><span class="sitara-status" ng-bind="x.exam_path_name"></span></td><td ng-bind="'Versi '+x.version_no"></td><td ng-bind="x.item_count+' komponen'"></td><td class="text-end table-main" ng-bind="rupiah(x.total_amount)"></td><td><div class="sitara-row-actions justify-content-end"><button class="btn btn-sm btn-outline-primary" ng-click="revise(x)">Revisi</button><button class="btn btn-sm btn-outline-danger" ng-click="deactivate(x)">Nonaktifkan</button></div></td></tr><tr ng-if="!loading&&!datas.length"><td colspan="7" class="sitara-empty">Belum ada tarif aktif.</td></tr></tbody></table></div></article>
<div class="modal fade" id="feeModal" tabindex="-1"><div class="modal-dialog modal-xl modal-dialog-centered modal-dialog-scrollable"><div class="modal-content"><form class="module-form" name="feeForm" ng-submit="save(feeForm)" novalidate><div class="modal-header"><div><h2 class="modal-title h5" ng-bind="model.id?'Revisi tarif & komponen':'Tambah tarif & komponen'"></h2><p class="small text-gray-600 mb-0">Tarif dibedakan berdasarkan jalur ujian. Revisi membuat versi baru.</p></div><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body p-4"><div class="alert alert-danger" ng-if="errorMessage" ng-bind="errorMessage"></div><div class="row g-3 mb-4"><div class="col-md-4"><label class="form-label">Program studi</label><select name="study_program_id" class="form-select" ng-model="model.study_program_id" required><option value="">Pilih prodi</option><option ng-repeat="x in programs|filter:{is_active:true}" ng-value="x.id" ng-bind="x.code+' — '+x.name"></option></select></div><div class="col-md-4"><label class="form-label">Jenis kegiatan</label><select name="activity_type_id" class="form-select" ng-model="model.activity_type_id" required><option value="">Pilih kegiatan</option><option ng-repeat="x in activityTypes|filter:{is_active:true}" ng-value="x.id" ng-bind="x.code+' — '+x.name"></option></select></div><div class="col-md-4"><label class="form-label">Jalur ujian</label><select name="exam_path_id" class="form-select" ng-model="model.exam_path_id" required><option value="">Pilih jalur</option><option ng-repeat="x in examPaths" ng-value="x.id" ng-bind="x.name"></option></select></div><div class="col-md-3"><label class="form-label">Berlaku mulai</label><input type="date" class="form-control" ng-model="model.effective_start_date"></div><div class="col-md-3"><label class="form-label">Berlaku sampai</label><input type="date" class="form-control" ng-model="model.effective_end_date"></div><div class="col-md-6"><label class="form-label">Catatan</label><input class="form-control" maxlength="1000" ng-model="model.notes"></div></div><div class="d-flex justify-content-between align-items-center mb-3"><h3 class="h6 mb-0">Komponen tagihan</h3><button type="button" class="btn btn-sm btn-outline-primary" ng-click="addItem()">Tambah komponen</button></div><div class="fee-item mb-2" ng-repeat="item in model.items track by $index"><div class="row g-2 align-items-end"><div class="col-md-2"><label class="form-label">Kode</label><input class="form-control text-uppercase" ng-model="item.code" required></div><div class="col-md-4"><label class="form-label">Nama komponen</label><input class="form-control" ng-model="item.name" required></div><div class="col-md-3"><label class="form-label">Nominal</label><input type="number" min="1" class="form-control" ng-model="item.amount" required></div><div class="col-md-2"><div class="form-check pb-2"><input class="form-check-input" type="checkbox" ng-model="item.is_required" id="required_{{$index}}"><label class="form-check-label" for="required_{{$index}}">Wajib</label></div></div><div class="col-md-1"><button type="button" class="btn btn-outline-danger w-100" ng-click="removeItem($index)" ng-disabled="model.items.length===1">×</button></div></div></div><div class="text-end h5 mt-3">Total: <span ng-bind="rupiah(total())"></span></div></div><div class="modal-footer"><button type="button" class="btn btn-outline-gray" data-bs-dismiss="modal">Batal</button><button type="submit" class="btn btn-primary" ng-disabled="saving" ng-bind="saving?'Menyimpan...':'Simpan tarif'"></button></div></form></div></div></div>
</section><script>window.SITARA_FEE_CONFIG=<?= json_encode(['baseUrl'=>site_url('keuangan/tarif')],JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT) ?>;window.SITARA_CSRF=<?= json_encode(['header'=>$csrfHeader,'hash'=>$csrfHash],JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT) ?>;</script><?= $this->endSection() ?>
